from h import *
add(6456614,"بجٹ کے موافق سلو کوکر چکن اور شکر قندی",
"پکانے کا وقت نہیں؟ رات کے کھانے کے لیے یہ سلو کوکر چکن آزمائیں۔ شکر قندی، ڈیجون رائی اور براؤن شوگر ایک منفرد اور مزیدار ذائقہ دیتے ہیں۔ سادہ بھاپ میں پکی بروکلی اور پھول گوبھی کی سائیڈ شامل کرنے سے یہ ایک مکمل کھانا بن جاتا ہے جس کے لیے 15 منٹ سے کم فعال تیاری درکار ہے۔",
"4","1 چکن ران 2-3 شکر قندی کے گول قتلوں اور 1 کپ بروکلی اور پھول گوبھی کے مکس کے ساتھ",
["1 پاؤنڈ بغیر ہڈی اور بغیر کھال کی چکن رانیں","1 درمیانی پیاز (کٹی ہوئی)","1 پاؤنڈ شکر قندی (چھلی ہوئی اور بڑے گول قتلوں میں کٹی ہوئی)","1 1/2 کپ کم سوڈیم چکن شوربہ","3 کھانے کے چمچ کم کیلوری والا براؤن شوگر کا متبادل","1/4 چائے کا چمچ خشک تھائم","2 کھانے کے چمچ ڈیجون رائی","1 پتا تیز پات","4 کپ تازہ یا منجمد بروکلی اور پھول گوبھی کی پھولیاں (بھاپ میں پکی ہوئی)"],
["چکن کو سلو کوکر میں رکھیں۔ چکن کے اوپر پیاز اور شکر قندی ڈالیں۔","چکن شوربہ، براؤن شوگر کا مرکب، تھائم، رائی اور تیز پات ڈالیں۔ ہلکی آنچ پر 5-6 گھنٹے پکائیں یا جب تک چکن پک نہ جائے۔","تیز پات نکال دیں اور بروکلی اور پھول گوبھی کے ساتھ پیش کریں۔"])
add(6457517,"پالک اور فیٹا بھرے ہوئے مشروم",
"پالک اور فیٹا بھرے ہوئے مشروم ایک خوشگوار اور لذیذ اپیٹائزر ہیں جو مشروم کے مٹی کی سی خوشبو والے ذائقے کو کریمی اور ذائقہ دار بھرائی کے ساتھ ملاتے ہیں۔ یہ لذیذ نوالے دعوتوں، تعطیلات کی محفلوں کے لیے بہترین اپیٹائزر ہیں، یا تاپاس کے دسترخوان میں مزیدار اضافے کے طور پر۔",
"8","2 بھرے ہوئے مشروم",
["16 بڑے کریمینی (بیبی بیلا) مشروم (صاف کیے ہوئے اور ڈنڈیاں نکالی ہوئی)","1 کھانے کا چمچ زیتون کا تیل","4 کپ پالک (کٹی ہوئی)","2 لہسن کی جوئیں (باریک کٹی ہوئی)","1/2 کپ فیٹا چیز (ریزہ ریزہ کی ہوئی)","1/2 کپ پارمیزان چیز (کم چکنائی والی، کدوکش کی ہوئی)","2 کھانے کے چمچ سادہ بغیر چکنائی والا یونانی دہی","1/8 چائے کا چمچ نمک","1/4 چائے کا چمچ کالی مرچ"],
["اوون کو 375 ڈگری فارن ہائیٹ پر پہلے سے گرم کریں اور بیکنگ ٹرے پر پارچمنٹ پیپر بچھا دیں۔","ایک کڑاہی میں 1 کھانے کا چمچ زیتون کا تیل درمیانی آنچ پر گرم کریں۔ باریک کٹا لہسن اور کٹی ہوئی پالک ڈالیں، اور 2–3 منٹ بھونیں جب تک پالک مرجھا نہ جائے اور اضافی نمی خشک نہ ہو جائے۔ کڑاہی کو چولھے سے ہٹا دیں۔","ایک مکسنگ باؤل میں بھونی ہوئی پالک اور لہسن کو ریزہ ریزہ فیٹا چیز، کدوکش کی ہوئی پارمیزان چیز، سادہ یونانی دہی، نمک اور کالی مرچ کے ساتھ ملا لیں۔ یقینی بنائیں کہ تمام اجزا اچھی طرح مل جائیں۔","صاف کیے ہوئے مشروم لیں اور ہر ٹوپی میں پالک اور چیز کا آمیزہ بھر دیں اور آہستگی سے دبا دیں۔","بھرے ہوئے مشروم تیار کی ہوئی بیکنگ ٹرے پر سجائیں۔ اگر چاہیں تو بھورا ہونے میں مدد کے لیے ان پر ہلکا سا کوکنگ اسپرے کر سکتے ہیں۔","بھرے ہوئے مشروم کو پہلے سے گرم اوون میں تقریباً 15–20 منٹ بیک کریں یا جب تک وہ نرم نہ ہو جائیں، اور بھرائی گرم ہو جائے اور ذرا بھوری ہو جائے۔"])
add(6457837,"تربوز لائم سلشی",
"چینی والے مشروبات کا یہ تازگی بخش متبادل آزمائیں! یہ تازہ تربوز سے بنایا جاتا ہے جس سے بغیر اضافی چینی کے ہلکا میٹھا ذائقہ ملتا ہے، ساتھ ہی چٹ پٹا لائم اور ٹھنڈا پودینہ۔ گرمیوں کے گرم دن کے لیے بہترین!",
"4","6 اونس (تقریباً 3/4 کپ)",
["2 کپ تربوز","2 کپ برف","1/4 کپ (تقریباً 2 لائم سے) لائم کا رس","2 کھانے کے چمچ (سجاوٹ کے لیے مزید) تازہ پودینے کے پتے"],
["تربوز، برف، لائم کا رس اور پودینہ بلینڈر میں اس وقت تک پیوری کریں جب تک سلشی جیسی ساخت نہ بن جائے۔ گلاسوں میں ڈالیں اور پودینے کی ایک ٹہنی سے سجائیں (اختیاری)۔"])
add(6458377,"پالک فیٹا ٹرکی برگر",
"یہ پالک فیٹا برگر عام بیف ٹکیوں کا زیادہ صحت بخش متبادل ہیں۔ کم کاربوہائیڈریٹ والے کھانے کے لیے لیٹس کے پتوں پر پیش کریں یا اگر آپ کا کھانے کا انداز اجازت دے تو پورے اناج کے بن پر۔ یہ مزیدار برگر یقیناً پورے خاندان کو پسند آئیں گے!",
"4","1 برگر",
["12 اونس منجمد پالک (پگھلائی ہوئی)","8 اونس کم چکنائی والا پسا ہوا ٹرکی","1/4 کپ سرخ پیاز (باریک کٹی ہوئی)","2 لہسن کی جوئیں (باریک کٹی ہوئی)","1 ثابت انڈا (پھینٹا ہوا)","2 کھانے کے چمچ پورے گندم کے بریڈ کرمبز","1/4 چائے کا چمچ کالی مرچ","2 کھانے کے چمچ کم چکنائی والی فیٹا چیز (ریزہ ریزہ کی ہوئی)","1 کھانے کا چمچ زیتون کا تیل (تلنے کے لیے)"],
["پگھلی ہوئی پالک سے اضافی پانی نچوڑ دیں۔","ایک بڑے پیالے میں نچوڑی ہوئی پالک، پسا ہوا ٹرکی، سرخ پیاز، لہسن، پھینٹا ہوا انڈا، بریڈ کرمبز، فیٹا اور مرچ ملا لیں۔","4 برابر ٹکیاں بنا لیں۔","ایک بڑی کڑاہی میں زیتون کا تیل درمیانی آنچ پر گرم کریں۔ ٹکیوں کو ہر طرف 4-5 منٹ پکائیں جب تک اچھی طرح پک نہ جائیں اور گہری سنہری بھوری نہ ہو جائیں۔"])
add(6459025,"مسالے دار لیموں دہی چکن ٹینڈرز",
"کھٹے اور دھواں دار، چکن کے یہ نرم نوالے گرمیوں کے کام کے دنوں کا آسان رات کا کھانا ہیں۔ صبح چکن کو میرینیڈ میں ملا دیں اور شام کو وہ گرل پر ڈالنے کے لیے تیار ہوں گے۔ تازہ بروکلی سلاد کی سائیڈ کے ساتھ پیش کریں۔",
"4","2 ٹینڈرز",
["8 ثابت چکن ٹینڈرلوئنز ((تقریباً 1 پاؤنڈ))","1 کپ سادہ بغیر چکنائی والا یونانی دہی","2 کھانے کے چمچ لیموں کا رس","1 کھانے کا چمچ لیموں کا چھلکا","1 کھانے کا چمچ پیپریکا","1 کھانے کا چمچ تازہ ادرک (کدوکش کی ہوئی)","1 چائے کا چمچ پسا ہوا زیرہ","1/2 چائے کا چمچ لہسن پاؤڈر","1/2 چائے کا چمچ نمک","1 درمیانا لیموں (چار حصوں میں کٹا ہوا، اختیاری، پیش کرنے کے لیے)"],
["لیموں کے چار حصوں کے علاوہ تمام اجزا ایک گیلن کے دوبارہ بند ہونے والے پلاسٹک بیگ میں ملا لیں۔ مضبوطی سے بند کریں اور اچھی طرح لگنے تک آگے پیچھے ہلائیں۔ 8 گھنٹے فریج میں رکھیں۔","ایک گرل پین پر فراخ دلی سے کوکنگ اسپرے لگا کر درمیانی تیز آنچ پر گرم کریں۔ چکن کو میرینیڈ سے نکالیں، میرینیڈ پھینک دیں، اور ہر طرف 3 منٹ گرل کریں یا جب تک بیچ میں گلابی پن ختم نہ ہو جائے۔ چاہیں تو لیموں کے چار حصوں کے ساتھ پیش کریں۔"])
add(6459632,"ابلا ہوا انڈا",
"انڈے قدرتی طور پر ذیابیطس کے لیے موزوں غذا ہیں جو پروٹین سے بھرپور اور کم کاربوہائیڈریٹ والے ہیں۔ مزید یہ کہ یہ کئی مختلف تراکیب میں بہترین جزو بنتے ہیں، بشمول ہمارے آسان ایگ سلاد کے۔ ایسا لگتا ہے کہ آن لائن ابلے ہوئے انڈوں کی سینکڑوں تراکیب ہیں، لیکن شیف جینیفر لیمپلو کی یہ ترکیب ہماری پسندیدہ ہے کیونکہ یہ تقریباً ناکام نہ ہونے والی ہے اور مستقل نتائج دیتی ہے۔ ان کا راز؟ جن انڈوں کو ابالنے کا ارادہ ہو انہیں ابالنے سے 10 دن سے 2 ہفتے پہلے خرید کر فریج میں رکھ دیں۔ پرانے انڈے تازہ انڈوں کے مقابلے میں بہتر ابلتے اور چھلتے ہیں۔ اس کے علاوہ، اگر آپ انہیں زیادہ پکا دیں تو زردی کے گرد ہلکی سبز حلقہ بن جاتا ہے۔ یہ پہلی بار پکانے والوں کو ڈرا دیتا ہے، لیکن فکر نہ کریں۔ اسے کھانا بالکل ٹھیک ہے، اس کا مطلب صرف یہ ہے کہ انڈا ذرا زیادہ پک گیا ہے۔",
"6","1 انڈا",
["6 بڑے انڈے","4 کپ پانی"],
["انڈوں کو ایک بڑے ساس پین کی تہہ میں ایک تہہ میں رکھیں اور ٹھنڈے پانی سے ڈھانپ دیں تاکہ انڈوں کے اوپر تقریباً ایک انچ پانی ہو۔","پین کو چولھے کے برنر پر رکھیں لیکن آنچ جلانے سے پہلے 20 منٹ کا ٹائمر لگا دیں۔","ٹائمر شروع کریں پھر آنچ تیز کریں اور ابال لیں۔ ابلنے پر آنچ ہلکی ابال تک کم کر دیں اور ٹائمر بجنے تک ہلکی آنچ پر پکائیں۔","جب ٹائمر بج جائے تو فوراً پین سے پانی نکال دیں پھر پین میں انڈوں کو آہستگی سے ہلائیں تاکہ چھلکے ٹوٹ جائیں۔","برف کے پانی سے ڈھانپ دیں اور برف کے پانی میں 15 منٹ رکھا رہنے دیں۔","برف کا پانی نکال دیں، پھر ہر انڈے کو کاغذی تولیے پر آہستگی سے لڑھکائیں تاکہ چھلکا ڈھیلا ہو جائے، اور انڈے سے چھلکا اتار دیں۔","ہوا بند ڈبے میں فریج میں ایک ہفتے تک رکھیں۔"])
add(6460004,"بیک کی ہوئی مسالے دار شکر قندی فرائز کم چکنائی والے دہی کی ڈپنگ ساس کے ساتھ",
"مزیدار مسالوں کے ساتھ، یہ آپ کے عام شکر قندی فرائز نہیں ہیں۔ کھٹی اور کریمی ڈپنگ ساس کے ساتھ پیش کیا جانے والا یہ سائیڈ وہ ہے جو آپ سال بھر بنانا چاہیں گے۔",
"6","½ کپ شکر قندی فرائز + 2 کھانے کے چمچ ڈپنگ ساس",
["2 بڑی شکر قندی (چھلی ہوئی اور فرائز کی شکل میں کٹی ہوئی)","1 کھانے کا چمچ زیتون کا تیل","1 چائے کا چمچ اسموکڈ پیپریکا","1/2 چائے کا چمچ زیرہ کے بیج","1/2 چائے کا چمچ لہسن پاؤڈر","1/2 چائے کا چمچ پیاز پاؤڈر","1/2 چائے کا چمچ نمک","1/4 چائے کا چمچ کالی مرچ","1 اسپرے، 0.25 گرام نان اسٹک کوکنگ اسپرے","1/2 کپ سادہ بغیر چکنائی والا یونانی دہی","1 کھانے کا چمچ لیموں کا رس","1 چائے کا چمچ میپل شربت","1/2 چائے کا چمچ پسا ہوا زیرہ"],
["اوون کو 425 ڈگری فارن ہائیٹ پر پہلے سے گرم کریں اور بیکنگ ٹرے پر پارچمنٹ پیپر بچھا دیں۔","ایک بڑے پیالے میں شکر قندی فرائز کو زیتون کے تیل، اسموکڈ پیپریکا، زیرہ، لہسن پاؤڈر، پیاز پاؤڈر، نمک اور کالی مرچ کے ساتھ یکساں طور پر لگنے تک ملا دیں۔","مسالا لگے شکر قندی فرائز تیار کی ہوئی بیکنگ ٹرے پر ایک تہہ میں سجائیں، یقینی بنائیں کہ وہ ایک دوسرے پر چڑھے ہوئے نہ ہوں۔","اضافی کرکراہٹ کے لیے فرائز پر ہلکا سا کوکنگ اسپرے کریں۔","پہلے سے گرم اوون میں 20–25 منٹ بیک کریں یا جب تک شکر قندی فرائز سنہری بھورے اور کرکرے نہ ہو جائیں، آدھے وقت پر انہیں پلٹ دیں۔","ڈپنگ ساس کے لیے: ایک چھوٹے پیالے میں کم چکنائی والا یونانی دہی، لیموں کا رس، میپل شربت اور پسا ہوا زیرہ پھینٹ کر ملا لیں۔","ڈپنگ ساس ساتھ الگ رکھ کر پیش کریں۔"])
add(6460699,"گرمیوں کا مرکزی ڈش سلاد",
"اس بھرپور سلاد کو، جس میں گرل کیا ہوا سرلوئن اسٹیک، بہت ساری سبزیاں اور لہسن والی ونیگریٹ شامل ہے، اس گرمی میں اپنے دسترخوان کا مرکز بننے دیں!\n\nیہ ترکیب اور مزید ہماری کک بک، \"کمپلیٹ منتھ آف میلز\" میں تلاش کریں، جہاں آپ کھانے کی منصوبہ بندی آسان بنانے کے لیے تراکیب کو ملا کر استعمال کر سکتے ہیں!",
"4","3 اونس گوشت + 1 ½ کھانے کے چمچ ڈریسنگ + 1 ⅓ کپ سبزیاں + 1 کپ ساگ",
["1 کپ منجمد مکئی","4 چائے کے چمچ کینولا تیل","3 لہسن کی جوئیں (قتلے کی ہوئی)","1/4 کپ سرخ شراب کا سرکہ","1 کھانے کا چمچ ڈیجون رائی","1/4 چائے کا چمچ کالی مرچ (حسب ذائقہ)","1/4 چائے کا چمچ چینی","12 اونس گرل کیا ہوا سرلوئن","1 کپ پکے ہوئے آلو (چوکور کٹے ہوئے)","1 کپ ہری پیاز (اسکیلین) (کٹی ہوئی)","1/2 کپ گاجر (باریک کٹی ہوئی)","1 کپ سرخ شملہ مرچ (چوکور کٹی ہوئی)","1 کپ ہری شملہ مرچ (چوکور کٹی ہوئی)","4 کپ بیبی سلاد کا ساگ"],
["مکئی کو پیکٹ کی ہدایات کے مطابق پکائیں۔","ایک چھوٹے ساس پین میں تیل گرم کریں؛ لہسن ڈالیں اور بھورا ہونے تک بھونیں۔","چولھے سے اتار کر ٹھنڈا کریں؛ چھان کر تیل الگ رکھ لیں؛ لہسن پھینک دیں۔","ایک بڑے پیالے میں الگ رکھا ہوا تیل، سرکہ، رائی، مرچ اور چینی ملا لیں۔ اگر چاہیں تو 1/2 چائے کا چمچ نمک ڈالیں۔","تیل کا آمیزہ مکئی، سرلوئن، آلو، ہری پیاز، گاجر اور دونوں قسم کی شملہ مرچوں کے ساتھ ملا لیں۔ اچھی طرح ملائیں، ڈھانپ دیں، اور ٹھنڈا کریں۔","سلاد کے ساگ کی تہہ والے پیالے میں پیش کریں۔"])
add(6460875,"لیموں شفون تازہ بیریز کے ساتھ",
"مصنفہ باربرا سیلگ براؤن کہتی ہیں، \"یہ مزیدار میٹھی کھٹی میٹھی ڈش بہت تازگی بخش ہے اور منہ میں گھل جاتی ہے۔ یہ اتنی ہلکی ہے کہ بغیر کسی احساس جرم کے لطف اٹھایا جا سکتا ہے۔ میٹھے میں پھل شامل کرنے سے کیلوری اور چکنائی کم ہوتی ہے۔ آپ اسے دعوت سے ایک یا دو دن پہلے بنا سکتے ہیں اور ذائقے ملنے کے بعد یہ اور بھی بہتر ہو جائے گی۔\"",
"6","1/2 کپ",
["1/3 کپ لیموں کا رس (تقریباً 2 بڑے لیموں سے)","1/2 کپ کم کیلوری والی چینی کا متبادل","4 بڑے انڈے","3 کپ تازہ بیریز (جیسے اسٹرابیری، بلیو بیری اور بلیک بیری)"],
["لیموں کا رس اور چینی کا متبادل ساس پین میں ڈالیں۔ چینی گھلنے تک گرم کریں اور ہلائیں۔ چولھے سے اتار لیں۔","انڈے پیالے میں توڑیں اور اچھی طرح پھینٹ لیں۔ پھینٹتے ہوئے لیموں اور چینی کا آمیزہ آہستہ آہستہ انڈوں میں ڈالیں۔ 1 منٹ پھینٹیں، پھر انڈوں کا آمیزہ ساس پین میں واپس ڈالیں۔","دھیمی سے درمیانی آنچ پر کئی منٹ پھینٹتے اور پکاتے رہیں جب تک انڈوں کا آمیزہ گاڑھا نہ ہو جائے۔ (جتنا زیادہ پھینٹیں گے، آمیزہ اتنا ہلکا ہو گا۔) آپ کے سامان کے مطابق اس میں 2-5 منٹ لگیں گے۔ آمیزہ اس وقت چولھے سے اتارنے کے لیے تیار ہے جب وہ چمچ کی پشت پر لگ جائے۔","ایک گھنٹے یا زیادہ کے لیے فریج میں رکھیں۔ ٹھنڈا ہونے پر یہ مزید گاڑھا ہو جائے گا۔","کچھ لیموں شفون میٹھے کے گلاس یا پیالے میں رکھیں اور اس پر بیریز چمچ سے ڈالیں۔ لیموں کریم اور بیریز کی تہیں بدل بدل کر لگائیں۔ اوپر بیریز ڈالیں۔"])
add(6461142,"چکن نگٹس ہنی مسٹرڈ ڈپنگ ساس کے ساتھ",
"یہ ترکیب نہ صرف مزیدار ہے بلکہ گردوں کے لیے بھی موزوں ہے۔ مختلف ڈپنگ ساسز آزمائیں، جیسے باربی کیو ساس، کری ساس، پھلوں کے اسپریڈ، یا کم سوڈیم سلاد ڈریسنگ۔",
"12","3 نگٹس + 1 کھانے کا چمچ ساس",
["3 کپ کارن فلیکس","2 کھانے کے چمچ 1% دودھ","1 بڑا انڈا","2 چائے کے چمچ ورسٹرشائر ساس","3 کھانے کے چمچ شہد","1/2 کپ مایونیز","1 کھانے کا چمچ پیلی رائی","1 پاؤنڈ بغیر ہڈی اور بغیر کھال کے چکن بریسٹ","1 اسپرے، 0.25 گرام نان اسٹک کوکنگ اسپرے"],
["رائی، مایونیز، شہد اور ورسٹرشائر ساس ایک چھوٹے پیالے میں ہلا کر ملا لیں۔ نگٹس کے پکنے تک ساس کو ٹھنڈا کرنے کے لیے فریج میں رکھیں۔","اوون کو 400°F پر پہلے سے گرم کریں۔","چکن بریسٹ کو 36 نوالے کے سائز کے ٹکڑوں میں کاٹ لیں۔","پھینٹا ہوا انڈا اور دودھ ایک چھوٹے پیالے میں ملا لیں۔ چکن کے ٹکڑوں کو انڈے کے آمیزے میں ڈبوئیں پھر کارن فلیکس کے چورے سے لپیٹنے کے لیے زپ لاک بیگ میں ہلائیں۔","نگٹس کو نان اسٹک کوکنگ اسپرے لگی بیکنگ ٹرے پر 15 منٹ بیک کریں جب تک پک نہ جائیں۔"])
add(6461143,"گلوٹین سے پاک کیلے کی ڈبل روٹی",
"گلوٹین سے پاک کیلے کی یہ ڈبل روٹی ویلنٹائن ڈے کے لیے اچھی ٹریٹ بن سکتی ہے اور یہ گلوٹین سے پاک ہے! ایک بڑی ڈبل روٹی کی بجائے آپ اسے چار منی لوف پینز میں بنا سکتے ہیں تاکہ چھوٹی ڈبل روٹیاں لپیٹ کر ویلنٹائن تحفے کے طور پر دی جا سکیں۔",
"16","1 قتلہ",
["1 اسپرے، 0.25 گرام نان اسٹک کوکنگ اسپرے","4 درمیانے کیلے (بہت پکے ہوئے، میش کیے ہوئے)","2 کھانے کے چمچ زیتون کا تیل","1 کپ کم چکنائی والی چھاچھ","2 بڑے انڈوں کی سفیدی","1 چائے کا چمچ وینیلا ایکسٹریکٹ","1/4 کپ کم یا بغیر کیلوری والا میٹھا","2 کپ گلوٹین سے پاک کثیر المقاصد بیکنگ مکس","3 کھانے کے چمچ پسے ہوئے السی کے بیج"],
["اوون کو 350 ڈگری فارن ہائیٹ پر پہلے سے گرم کریں۔ 8x4 انچ کے لوف پین پر کوکنگ اسپرے لگا دیں۔","ایک بڑے پیالے میں کیلے، تیل، چھاچھ، انڈوں کی سفیدی، وینیلا اور کم یا بغیر کیلوری والا میٹھا ملا لیں؛ اچھی طرح ملائیں۔","گلوٹین سے پاک بیکنگ مکس اور السی کے بیج ڈالیں اور ملنے تک ملائیں۔ آمیزہ لوف پین میں ڈال دیں۔ 30–35 منٹ بیک کریں یا جب تک بیچ میں ڈالی گئی ٹوتھ پک صاف نہ نکلے۔"])
