add(6461989,"ٹوفو مونگ پھلی کی ساس، بروکولینی اور کینوا کے ساتھ",
"اس ٹوفو کی ترکیب کے ذائقوں کے مزیدار توازن سے لطف اٹھائیں۔ کرکرا ٹوفو کریمی مونگ پھلی کی ساس میں لپٹا ہوا ہے اور نرم بروکولینی اور ہلکے کینوا کے ساتھ پیش کیا جاتا ہے۔ ویگن میل پیٹرن کی یہ ڈش نہ صرف غذائیت بخش ہے بلکہ بے حد تسلی بخش بھی ہے۔",
"4","½ کپ پکا ہوا کینوا، 1 کپ ٹوفو، ½ کپ بروکولینی",
["1 ثابت لائم","1 انچ کا ٹکڑا تازہ ادرک (چھلا ہوا اور باریک کٹا ہوا)","1/4 کپ پاؤڈر مونگ پھلی کا مکھن","2 کھانے کے چمچ پانی","1 کھانے کا چمچ سویا ساس","2 چائے کے چمچ براؤن شوگر","21 اونس ایکسٹرا فرم ٹوفو (پانی نکالا ہوا اور دبایا ہوا)","2 چائے کے چمچ کارن اسٹارچ","1 کھانے کا چمچ زیتون کا تیل","2 گچھے بروکولینی","2 کپ پکا ہوا کینوا"],
["لائم کا رس ایک چھوٹے پیالے میں نچوڑیں۔","ادرک، مونگ پھلی کے مکھن کا پاؤڈر، پانی، سویا ساس اور براؤن شوگر ایک پیالے میں ڈالیں۔ ساس بنانے کے لیے پھینٹ کر ملا لیں۔","ایک بڑی کڑاہی کو درمیانی آنچ پر پہلے سے گرم کریں۔","جب کڑاہی گرم ہو رہی ہو تو ٹوفو کو درمیانے چوکور ٹکڑوں میں کاٹ لیں۔ ایک درمیانے پیالے میں رکھیں، کارن اسٹارچ چھڑکیں، پھر لپیٹنے کے لیے آہستگی سے ملا دیں۔","جب کڑاہی گرم ہو جائے تو 2 چائے کے چمچ تیل ڈالیں اور تہہ کو ڈھانپنے کے لیے گھما دیں۔ ٹوفو ڈالیں اور وقفے وقفے سے پلٹتے ہوئے پین میں فرائی کریں، جب تک بھورا اور کرکرا نہ ہو جائے، 5–7 منٹ۔ ٹوفو کو پیالے میں منتقل کر دیں۔","کڑاہی کو درمیانی آنچ پر واپس رکھیں۔ باقی تیل اور بروکولینی کڑاہی میں ڈالیں۔ بار بار ہلاتے ہوئے نرم لیکن کرکری ہونے تک پکائیں، 4–5 منٹ۔","پیش کرنے کے لیے کینوا، ٹوفو اور بروکولینی کو پیالوں میں تقسیم کریں۔ ٹوفو پر مونگ پھلی کی ساس ڈالیں۔"])
add(6462700,"بیک کی ہوئی پارمیزان بریڈڈ زوکینی",
"اطالوی انداز کی بریڈڈ زوکینی ایک کرکری اور بچوں کی پسندیدہ سائیڈ ڈش بناتی ہے جو نہ صرف مزیدار ہے بلکہ ذیابیطس کے لیے موزوں اور کم کاربوہائیڈریٹ والی بھی ہے۔",
"6","1/2 کپ",
["1 کپ بریڈ کرمبز","1/2 کپ پارمیزان چیز (کدوکش کی ہوئی، کم سوڈیم)","1 چائے کا چمچ خشک اوریگانو","1 چائے کا چمچ لہسن پاؤڈر","1/8 چائے کا چمچ نمک","1/4 چائے کا چمچ کالی مرچ","2 بڑے انڈے (پھینٹے ہوئے)","2 درمیانی زوکینی (گول قتلوں میں کٹی ہوئی)","1 اسپرے نان اسٹک کوکنگ اسپرے (زیتون کے تیل والا)"],
["اوون کو 425 ڈگری فارن ہائیٹ پر پہلے سے گرم کریں۔","ایک پیالے میں بریڈ کرمبز، کدوکش کی ہوئی پارمیزان چیز، خشک اوریگانو، لہسن پاؤڈر، نمک اور کالی مرچ ملا لیں۔","ہر زوکینی کے گول قتلے کو پھینٹے ہوئے انڈوں میں ڈبوئیں، یقینی بنائیں کہ وہ اچھی طرح لگ جائیں۔","انڈے میں ڈوبے ہر زوکینی کے قتلے پر بریڈ کرمبز کا آمیزہ لگائیں، کرمبز کو زوکینی پر دبا کر چپکائیں۔","بریڈڈ زوکینی کے قتلوں کو زیتون کے تیل والے کوکنگ اسپرے لگی بیکنگ ٹرے پر رکھیں۔","بریڈڈ زوکینی کے قتلوں کے اوپر ہلکا سا زیتون کے تیل والا کوکنگ اسپرے کریں۔","پہلے سے گرم اوون میں 20 منٹ بیک کریں یا جب تک زوکینی نرم نہ ہو جائے اور تہہ سنہری بھوری ہو جائے۔","زوکینی کو اوون سے نکالیں اور سرونگ تھالی میں منتقل کریں۔"])
